BEGIN;
create temp table assertion_count(n integer);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create temp table st(k text primary key,v jsonb);
insert into public.properties(id,org_id,name)values('ee590000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Legal review SQL fixture'),('ee590000-0000-4000-8000-000000000002','22222222-2222-2222-2222-222222222222','Other legal review SQL fixture');
create function pg_temp.read_legal(b jsonb default'{}',p uuid default'ee590000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.read_legal_reviews(p,'11111111-1111-1111-1111-111111111111',b)$$;
create function pg_temp.decide(i uuid,b jsonb,p uuid default'ee590000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.decide_legal_review(i,p,'11111111-1111-1111-1111-111111111111',b)$$;
create function pg_temp.draft()returns jsonb language sql as $$select jsonb_build_object('jurisdiction','Synthetic fixture jurisdiction','legalEntityName','Synthetic fixture entity','effectiveAt','2026-01-01T01:02:03Z','documents',(select jsonb_object_agg(k,jsonb_build_object('text','Exact supplied fixture text '||k,'sourceUrl','https://example.invalid/source','reviewedAt','2025-12-01T10:20:30+02:00','retainedExtra',jsonb_build_object('original','keep this')))from unnest(array['privacy_policy','terms','accessibility','fair_housing','pricing_disclaimer','analytics_consent','communications_consent'])k),'sourceReferences','[{"sourceType":"client counsel","sourceId":"private-reference","sourceUrl":"https://example.invalid/original","extra":"preserved"}]'::jsonb)$$;
create function pg_temp.save_input(source_id uuid default null,body jsonb default null)returns jsonb language sql as $$select jsonb_build_object('operation','save','expectedStateHash',public.knowledge_hash(public.legal_review_state('ee590000-0000-4000-8000-000000000001')),'sourceVersionId',source_id,'draft',coalesce(body,pg_temp.draft()),'reason','Retain exact supplied fixture draft')$$;
create function pg_temp.review_input(i uuid,op text default'approve')returns jsonb language sql as $$select jsonb_build_object('operation',op,'versionId',i,'versionHash',public.knowledge_hash(to_jsonb(r)),'expectedStateHash',public.knowledge_hash(public.legal_review_state(r.property_id)),'confirmed',true,'reason','Review exact saved legal fixture')from public.property_legal_configs r where id=i$$;
select pg_temp.check_it(pg_temp.read_legal()->>'total'='0'and pg_temp.read_legal()->'activeVersionId'='null','empty legal state does not invent approval');
insert into st values('save',pg_temp.save_input());
select pg_temp.check_it(pg_temp.decide('ee590000-0000-4000-8000-000000000010',(select v from st where k='save'))->>'state'='saved','exact draft saved');
select pg_temp.check_it(pg_temp.decide('ee590000-0000-4000-8000-000000000010',(select v from st where k='save'))->>'state'='replayed','lost draft response recovers same version');
select pg_temp.check_it(pg_temp.decide('ee590000-0000-4000-8000-000000000010',(select v||'{"reason":"Different draft request"}'from st where k='save'))->>'state'='request_conflict','changed request does not reuse saved identity');
select pg_temp.check_it((select privacy_policy->>'reviewedAt'='2025-12-01T10:20:30+02:00'and privacy_policy->'retainedExtra'='{"original":"keep this"}'and source_references=pg_temp.draft()->'sourceReferences'from public.property_legal_configs where id='ee590000-0000-4000-8000-000000000010'),'all document metadata and references retained exactly');
select pg_temp.check_it(pg_temp.read_legal()->'activeVersionId'='null','draft is not an approval');
insert into st values('approve',pg_temp.review_input('ee590000-0000-4000-8000-000000000010'));
select pg_temp.check_it(pg_temp.decide('ee590000-0000-4000-8000-000000000011',(select v from st where k='approve'))->>'state'='saved','explicit saved version approved');
select pg_temp.check_it(pg_temp.decide('ee590000-0000-4000-8000-000000000011',(select v from st where k='approve'))->>'state'='replayed','lost approval recovers without second decision');
select pg_temp.check_it((select status='approved'and approved_by='11111111-1111-1111-1111-111111111111'and approved_at is not null from public.property_legal_configs where id='ee590000-0000-4000-8000-000000000010'),'approval uses actual actor and server time');
insert into public.property_onboarding_snapshots(id,org_id,property_id,status,content_hash,snapshot_payload)select'ee590000-0000-4000-8000-000000000080',org_id,property_id,'approved',repeat('a',64),jsonb_build_object('legal',to_jsonb(r))from public.property_legal_configs r where id='ee590000-0000-4000-8000-000000000010';
insert into st values('pinnedLegal',(select to_jsonb(r)from public.property_legal_configs r where id='ee590000-0000-4000-8000-000000000010'));
select pg_temp.check_it(public.legal_snapshot_matches_current('ee590000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222',(select v from st where k='pinnedLegal')),'current exact legal snapshot accepted');
insert into public.shared_context_snapshots(id,org_id,property_id,source_domain,context_hash,context_payload)values('ee590000-0000-4000-8000-000000000085','22222222-2222-2222-2222-222222222222','ee590000-0000-4000-8000-000000000001','forgestudio.generation','fixture-legal-source',jsonb_build_object('version','forgestudio.context.v1','propertyId','ee590000-0000-4000-8000-000000000001','contextHash','fixture-legal-source','policy',jsonb_build_object('legalConfigId','ee590000-0000-4000-8000-000000000010'),'sourceRecords',jsonb_build_object('legal:ee590000-0000-4000-8000-000000000010',jsonb_build_object('kind','legal','id','ee590000-0000-4000-8000-000000000010','values',public.read_forgestudio_source_record('ee590000-0000-4000-8000-000000000001','legal','ee590000-0000-4000-8000-000000000010'))),'sources',jsonb_build_array(jsonb_build_object('id','legal_policy:ee590000-0000-4000-8000-000000000010','kind','legal_policy','recordKey','legal:ee590000-0000-4000-8000-000000000010','label','Supplied fixture policy','content','Fixture accessibility statement','allowedUses','["claim"]'::jsonb))));
insert into st values('claim','{"claims":[{"text":"Supplied fixture statement","type":"accessibility","citations":[{"sourceType":"legal_policy","sourceId":"legal_policy:ee590000-0000-4000-8000-000000000010"}]}],"variants":[]}');
select pg_temp.check_it(public.check_forgestudio_sources('ee590000-0000-4000-8000-000000000001','ee590000-0000-4000-8000-000000000085',(select v from st where k='claim'))->>'state'='current','saved ForgeStudio legal source is initially current');
select pg_temp.decide('ee590000-0000-4000-8000-000000000020',pg_temp.save_input('ee590000-0000-4000-8000-000000000010',jsonb_set(pg_temp.draft(),'{documents,terms,text}','"New supplied fixture terms"')));
select pg_temp.check_it(pg_temp.read_legal()->>'activeVersionId'='ee590000-0000-4000-8000-000000000010'and(select status='approved'from public.property_onboarding_snapshots where id='ee590000-0000-4000-8000-000000000080'),'new draft preserves approved legal and readiness');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),(select v from st where k='approve'))->>'state'='legal_changed','old review cannot approve changed source inventory');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.review_input('ee590000-0000-4000-8000-000000000010'))->>'state'='version_not_current','only latest draft may be approved');
create function pg_temp.fail_legal_action()returns trigger language plpgsql as $$begin if new.action='legal.approved'then raise exception 'Synthetic legal action failure';end if;return new;end$$;
create trigger legal_fixture_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_legal_action();
do $$begin begin perform pg_temp.decide('ee590000-0000-4000-8000-000000000021',pg_temp.review_input('ee590000-0000-4000-8000-000000000020'));raise exception 'Expected failure'using errcode='P0002';exception when sqlstate'P0001'then if sqlerrm<>'Synthetic legal action failure'then raise;end if;perform pg_temp.check_it(true,'approval history failure reaches atomic boundary');end;end$$;
drop trigger legal_fixture_failure on public.shared_action_events;
select pg_temp.check_it((select status='approved'from public.property_legal_configs where id='ee590000-0000-4000-8000-000000000010')and(select status='draft'from public.property_legal_configs where id='ee590000-0000-4000-8000-000000000020')and(select status='approved'from public.property_onboarding_snapshots where id='ee590000-0000-4000-8000-000000000080'),'failed approval preserves old approval draft and readiness together');
select pg_temp.decide('ee590000-0000-4000-8000-000000000021',pg_temp.review_input('ee590000-0000-4000-8000-000000000020'));
select pg_temp.check_it((select status='superseded'from public.property_legal_configs where id='ee590000-0000-4000-8000-000000000010')and(select status='approved'from public.property_legal_configs where id='ee590000-0000-4000-8000-000000000020')and(select status='stale'from public.property_onboarding_snapshots where id='ee590000-0000-4000-8000-000000000080'),'replacement atomically supersedes and invalidates readiness');
select pg_temp.check_it((select jsonb_array_length(after_state->'invalidatedReadiness')=1 and after_state->'invalidatedReadiness'->0->>'id'='ee590000-0000-4000-8000-000000000080'from public.property_legal_decisions where id='ee590000-0000-4000-8000-000000000021'),'exact invalidated readiness evidence retained');
select pg_temp.check_it(public.check_forgestudio_sources('ee590000-0000-4000-8000-000000000001','ee590000-0000-4000-8000-000000000085',(select v from st where k='claim'))->>'state'='source_review_required','legal replacement holds downstream ForgeStudio claims');
select pg_temp.check_it(not public.legal_snapshot_matches_current('ee590000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222',(select v from st where k='pinnedLegal')),'old legal source no longer current');
do $$begin begin update public.property_onboarding_snapshots set status='approved'where id='ee590000-0000-4000-8000-000000000080';raise exception 'Expected stale guard'using errcode='P0002';exception when sqlstate'P0001'then if sqlerrm not like'The legal approval changed%'then raise;end if;perform pg_temp.check_it(true,'late readiness approval cannot revive an old legal source');end;end$$;
insert into public.property_onboarding_snapshots(id,org_id,property_id,status,content_hash,snapshot_payload)values('ee590000-0000-4000-8000-000000000081','22222222-2222-2222-2222-222222222222','ee590000-0000-4000-8000-000000000001','ready',repeat('b',64),jsonb_build_object('legal',(select v from st where k='pinnedLegal')));
select pg_temp.check_it((select status='stale'from public.property_onboarding_snapshots where id='ee590000-0000-4000-8000-000000000081'),'late snapshot build with former legal source is held');
select pg_temp.decide('ee590000-0000-4000-8000-000000000022',pg_temp.review_input('ee590000-0000-4000-8000-000000000020','withdraw'));
select pg_temp.check_it(pg_temp.read_legal()->'activeVersionId'='null'and pg_temp.read_legal()->>'approvedCount'='0','withdrawal leaves no fallback approval');
select pg_temp.check_it((select approved_by='11111111-1111-1111-1111-111111111111'and approved_at is not null from public.property_legal_configs where id='ee590000-0000-4000-8000-000000000020'),'withdrawal retains original approval attribution');
select pg_temp.decide('ee590000-0000-4000-8000-000000000030',pg_temp.save_input(null,jsonb_set(pg_temp.draft(),'{effectiveAt}',to_jsonb(to_char(clock_timestamp()+interval'1 day','YYYY-MM-DD"T"HH24:MI:SS')||'+00:00'))));
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.review_input('ee590000-0000-4000-8000-000000000030'))->>'state'='review_incomplete','future effective drafts cannot be approved early');
select pg_temp.decide('ee590000-0000-4000-8000-000000000031',pg_temp.review_input('ee590000-0000-4000-8000-000000000030','reject'));
select pg_temp.check_it((select status='rejected'from public.property_legal_configs where id='ee590000-0000-4000-8000-000000000030'),'rejected draft retained');
select pg_temp.decide('ee590000-0000-4000-8000-000000000040',pg_temp.save_input(null,jsonb_set(pg_temp.draft(),'{documents,privacy_policy,text}','""')));
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.review_input('ee590000-0000-4000-8000-000000000040'))->>'state'='review_incomplete','incomplete draft saves but cannot approve');
select pg_temp.check_it(pg_temp.read_legal('{"kind":"version","versionId":"ee590000-0000-4000-8000-000000000040"}','ee590000-0000-4000-8000-000000000002')->>'state'='not_found','version read property scoped');
select pg_temp.check_it(pg_temp.decide('ee590000-0000-4000-8000-000000000010',(select v from st where k='save'),'ee590000-0000-4000-8000-000000000002')->>'state'='request_conflict','request identity property scoped');
select pg_temp.check_it(pg_temp.decide('ee590000-0000-4000-8000-000000000050',jsonb_build_object('operation','cancel_unused','inputHash',repeat('c',64),'reason','Stop unused draft request'))->>'state'='cancelled','unused legal request cancellation retained');
select pg_temp.check_it(pg_temp.decide('ee590000-0000-4000-8000-000000000050',pg_temp.save_input())->>'state'='decision_cancelled','delayed cancelled request fenced');
select pg_temp.check_it(pg_temp.decide('ee590000-0000-4000-8000-000000000021',jsonb_build_object('operation','cancel_unused','inputHash',repeat('d',64),'reason','Stop unused approval request'))->>'state'='replayed','unused cancellation never undoes an approval');
select pg_temp.check_it(pg_temp.read_legal('{"kind":"decision","decisionId":"ee590000-0000-4000-8000-000000000021"}')->>'state'='ready','saved approval recoverable');
update public.profiles set role='viewer'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(pg_temp.read_legal()->'canManage'='false'and pg_temp.decide(gen_random_uuid(),pg_temp.save_input())->>'state'='forbidden','viewer read never grants write');
update public.profiles set role='admin'where id='11111111-1111-1111-1111-111111111111';
select set_config('p11.legal_review_scope','',true);
do $$begin begin update public.property_legal_configs set terms='{"text":"unrecorded replacement"}'where id='ee590000-0000-4000-8000-000000000040';raise exception 'Expected content guard'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'adopted content cannot be changed directly');end;begin update public.property_legal_decisions set input='{}'where id='ee590000-0000-4000-8000-000000000021';raise exception 'Expected history guard'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'legal decision history immutable');end;end$$;
select pg_temp.check_it(not has_table_privilege('authenticated','public.property_legal_configs','select')and not has_table_privilege('authenticated','public.property_legal_configs','update')and not has_table_privilege('authenticated','public.property_legal_decisions','select')and not has_function_privilege('anon','public.decide_legal_review(uuid,uuid,uuid,jsonb)','execute'),'direct legal review access closed');
-- A source ID from another property cannot be reassigned through the old neighborhood endpoint.
insert into public.property_points_of_interest(id,org_id,property_id,name,category)values('ee590000-0000-4000-8000-000000000090','22222222-2222-2222-2222-222222222222','ee590000-0000-4000-8000-000000000002','Private source','fixture');
do $$begin begin update public.property_points_of_interest set property_id='ee590000-0000-4000-8000-000000000001'where id='ee590000-0000-4000-8000-000000000090';raise exception 'Expected ownership guard'using errcode='P0002';exception when sqlstate'P0001'then if sqlerrm<>'Neighborhood source ownership is immutable'then raise;end if;perform pg_temp.check_it(true,'neighborhood source cannot be reparented');end;end$$;
select pg_temp.check_it((select property_id='ee590000-0000-4000-8000-000000000002'from public.property_points_of_interest where id='ee590000-0000-4000-8000-000000000090'),'failed reparent retains original owner');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id='ee590000-0000-4000-8000-000000000001'and(training_eligible or(request::text||result::text)like'%Exact supplied%')),'activity retains safe hashes and no training eligibility');
insert into public.organizations(id,name)values('ee590000-0000-4000-8000-000000000099','Legal scope SQL fixture');
update public.profiles set org_id='ee590000-0000-4000-8000-000000000099'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(pg_temp.read_legal()->>'state'='forbidden','member transfer hides former legal decisions');
SET LOCAL session_replication_role=replica;
update public.properties set org_id='ee590000-0000-4000-8000-000000000099'where id='ee590000-0000-4000-8000-000000000001';
SET LOCAL session_replication_role=origin;
select pg_temp.check_it(pg_temp.read_legal()->>'state'='scope_changed','property transfer does not rebind private legal history');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.save_input())->>'state'='scope_changed','new organization cannot adopt earlier legal content by saving');
select pg_temp.check_it(pg_temp.decide('ee590000-0000-4000-8000-000000000021',(select v from st where k='approve'))->>'state'='request_conflict','transferred actor cannot replay old org decision');
SET LOCAL session_replication_role=replica;
update public.properties set org_id='22222222-2222-2222-2222-222222222222'where id='ee590000-0000-4000-8000-000000000001';
SET LOCAL session_replication_role=origin;
update public.profiles set org_id='22222222-2222-2222-2222-222222222222'where id='11111111-1111-1111-1111-111111111111';
-- Native history and version paging remain complete beyond REST limits.
insert into st values('page',pg_temp.read_legal());
select set_config('p11.legal_review_scope','ee590000-0000-4000-8000-000000000001',true);
insert into public.property_legal_configs(org_id,property_id,version,status)select'22222222-2222-2222-2222-222222222222','ee590000-0000-4000-8000-000000000001',n+100,'draft'from generate_series(1,1001)n;
select pg_temp.check_it(pg_temp.read_legal()->>'total'='1005','native legal version count complete');
select pg_temp.check_it(jsonb_array_length(pg_temp.read_legal('{"offset":1000}')->'items')=5,'last legal page not silently truncated');
select pg_temp.check_it(pg_temp.read_legal(jsonb_build_object('expectedHash',(select v->>'pageHash'from st where k='page')))->>'state'='history_changed','changed version inventory holds paging');
insert into public.property_legal_decisions(id,property_id,org_id,actor_id,version_id,kind,input,input_hash,before_state,after_state,result)select gen_random_uuid(),'ee590000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','ee590000-0000-4000-8000-000000000040','saved','{"reason":"Synthetic full history"}','fixture','{}','{}','{}'from generate_series(1,1001);
select pg_temp.check_it((pg_temp.read_legal('{"kind":"history"}')->>'total')::int>1000 and jsonb_array_length(pg_temp.read_legal('{"kind":"history","offset":1000}')->'items')>0,'full legal decision history readable');
select n as passed_assertions from assertion_count;
ROLLBACK;
